@dataclass(frozen=True)
class AppendixAEntry:
    hazard_family: str
    source_name: str
    item_type: str
    source_url: str
    status: str
    mapped_models: Sequence[str] = ()
    notes: str = ""
    # (label, Sphinx docname) links for entries that are not models, e.g. an external simulator.
    mapped_docs: Sequence[Tuple[str, str]] = ()


